test('lineVat calculates VAT on full line amount', () => {
  const line = { qty: 10, unitPrice: 1000, vatRate: 21 };
  const r = lineVat(line);
  assert.ok(r.ok);
  assert.equal(r.value, 2100);
});

test('lineVat calculates VAT on amount after discount', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 };
  const r = lineVat(line);
  assert.ok(r.ok);
  const expected = roundCents((9000 * 21) / 100);
  assert.equal(r.value, expected);
});

